// The Hunter / Загонщик (Дар Кхорна, wdbc-1rno, стр. 453-460). Книга:
// «Если в пределах видимости чемпиона есть псайкер, он может за полное
// действие потратить Очко Бесчестия и призвать Гончую Плоти в Истинной
// Форме. Гончая действует в его инициативу и нападает на ближайшего
// псайкера. Убив свою добычу, гончая возвращается в Варп.»
//
// Разбор пробела (09.09.2026, решение пользователя): автоатак ни для
// одного существа в системе нет — «нападает на ближайшего псайкера»
// реализовано как подсказка в карточке призыва (module/combat/
// the-hunter.mjs::spawnHunterHound, там же и сама Гончая, и синхронизация
// инициативы «сразу после чемпиона»), реальную атаку ведёт игрок/ГМ
// вручную. «Возвращается в Варп» привязано к кнопке «Констатировать
// смерть» (module/hooks.mjs) — появляется сама, когда добыча подтверждена
// убитой именно этой Гончей.
//
// Throw (не ui.notifications.warn + return, как у Красного Солнца) —
// намеренно: capabilityCostPool списывается ПОСЛЕ успешного выполнения
// кода (runMechScriptEntry), а непройденный гейт видимости псайкера/ОД не
// должен стоить Очка Бесчестия впустую.
const championToken = token?.document ?? token;
if (!championToken?.parent) {
  throw new Error("У чемпиона нет токена на текущей сцене.");
}
if (!nearestVisiblePsyker(championToken)) {
  throw new Error("В пределах видимости нет псайкера — Загонщика применить нельзя.");
}
const FULL_ACTION_AP = 2;
if (!canSpendActionPoints(actor, FULL_ACTION_AP)) {
  throw new Error("Не хватает Очков Действия (нужно 2, полное действие).");
}
if (!(await spendActionPoints(actor, FULL_ACTION_AP))) {
  throw new Error("Не удалось списать Очки Действия.");
}
await defaultSpawnHunterHoundFn(actor.uuid, item.id);
